!function(e){function t(t){for(var r,i,d=t[0],o=t[1],m=t[2],g=0,_=[];g<d.length;g++)i=d[g],Object.prototype.hasOwnProperty.call(p,i)&&p[i]&&_.push(p[i][0]),p[i]=0;for(r in o)Object.prototype.hasOwnProperty.call(o,r)&&(e[r]=o[r]);for(c&&c(t);_.length;)_.shift()();return n.push.apply(n,m||[]),a()}function a(){for(var e,t=0;t<n.length;t++){for(var a,i=n[t],d=!0,o=1;o<i.length;o++)a=i[o],0!==p[a]&&(d=!1);d&&(n.splice(t--,1),e=r(r.s=i[0]))}return e}function r(t){if(i[t])return i[t].exports;var a=i[t]={i:t,l:!1,exports:{}};return e[t].call(a.exports,a,a.exports,r),a.l=!0,a.exports}var i={},p={7:0},n=[];r.m=e,r.c=i,r.d=function(e,t,a){r.o(e,t)||Object.defineProperty(e,t,{enumerable:!0,get:a})},r.r=function(e){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(e,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(e,"__esModule",{value:!0})},r.t=function(e,t){if(1&t&&(e=r(e)),8&t)return e;if(4&t&&"object"==typeof e&&e&&e.__esModule)return e;var a=Object.create(null);if(r.r(a),Object.defineProperty(a,"default",{enumerable:!0,value:e}),2&t&&"string"!=typeof e)for(var i in e)r.d(a,i,function(t){return e[t]}.bind(null,i));return a},r.n=function(e){var t=e&&e.__esModule?function(){return e.default}:function(){return e};return r.d(t,"a",t),t},r.o=function(e,t){return Object.prototype.hasOwnProperty.call(e,t)},r.p="";var d=window.webpackJsonp=window.webpackJsonp||[],o=d.push.bind(d);d.push=t,d=d.slice();for(var m=0;m<d.length;m++)t(d[m]);var c=o;n.push([106,0]),a()}({106:function(e,t,a){"use strict";a.r(t);var r=a(0);Object(r.a)("de","army",a(107),a(1))},107:function(e){e.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"半履带装甲车","link":"de_army#de_army_avhtv"}],"model":"250/3型半履带装甲通讯指挥车","description":"<p>250/3型半履带装甲通讯指挥车是德军专门用于装甲部队通讯联络、战场指挥以及引导飞机对地攻击等工作的一种无线通讯指挥车辆。它用250的车体改装，主要加装了1至2台大功率的电台和车外天线，有远距离无线通讯功能；该型车一般配备给德军的营、连级指挥部使用，亦有少数成为德军高级指挥官的专用车作通讯指挥用。</p><p>1941年秋天，在250早期型车体开始量产的同时，德军也几乎同步开始了250/3型半履带装甲通讯指挥车的改装，随后继续在250新车体上改装，根据所安装的不同型号的车载电台、不同形状的车外天线以及不同的用途，又分为Ⅰ、Ⅱ、Ⅲ、Ⅳ共4种子型号。</p><p>二战期间，有不少数量的250/3型半履带装甲通讯指挥车配备给德军装甲部队和空军部队，使德军具备了较好的战场协调与指挥调度能力，在各个战场上发挥了不小作用。</p>","part1title":"","part1description":"","part1content":[{"image":"{{text}}用250新车体改装的Sdkfz 250/3Ⅰ（Neu）型半履带装甲通讯指挥车{{image}}imgs/de/army/de_army_avhtv2503_11.jpg{{text}}用250旧车体改装的Sdkfz 250/3Ⅰ（Alt）型半履带装甲通讯指挥车<br>该车已更换了星形天线，属于中期生产的车辆。{{image}}imgs/de/army/de_army_avhtv2503_12.jpg","description":"<h6>Sdkfz 250/3 Ⅰ型半履带装甲通讯指挥车</h6><p>Sdkfz 250/3 Ⅰ型半履带装甲通讯指挥车战斗全重5.35吨，核载人员4人：1名驾驶员、1名车长和2名无线电操作员。车内除250装甲车标配的FuG Spr型电台外，在车厢后部位置还安装有1台FuG12型的大功率电台，早期在车外竖一根标准2米天线杆进行无线收发，后期更换为收发效果更好的星形天线；该车上还配备有1挺MG34或MG42机枪作自卫或攻击用。</p><p>该型车主要装备给德军装甲部队和摩托化步兵部队的营、连级指挥部使用，负责各装甲部队的联络、协调和指挥。 </p><h6>Sdkfz 250/3 Ⅱ型半履带装甲通讯指挥车</h6><p>外形与结构与250/3Ⅰ型相同，但车内电台与所负任务与250/3Ⅰ型不同。</p><p>250/3Ⅱ型装备的是FuG 7型大功率电台，包括一台超短波接收机和一台20瓦功率的发射机，车外竖一根标准2米天线杆。该型车主要装备空军地面部队，供空军派驻的联络官作引导飞机对地攻击用。</p>","caption":""},{"image":"{{text}}用250旧车体改装的Sdkfz 250/3 Ⅳ（Alt）型半履带装甲通讯指挥车{{image}}imgs/de/army/de_army_avhtv2503_13.jpg{{text}}用250新车体改装的Sdkfz 250/3 Ⅳ（Neu）型半履带装甲通讯指挥车{{image}}imgs/de/army/de_army_avhtv2503_14.jpg","description":"<h6>SdKfz 250/3 Ⅳ型半履带装甲通讯指挥车</h6><p>该车是一种多功能、多用途的无线电通讯指挥车，它最大特点是在车体外安装了具有更强收发信号能力的框形天线，该车可配备给德军各兵种的连以上指挥单位使用，并根据不同级别的指挥单位和不同兵种的需求配备不同型号的电台，成为各级指挥官的通讯指挥车；德军也有一些高级指挥官选用了此型车作其通讯指挥车用。</p><h6>SdKfz 250/3 Ⅲ型半履带装甲通讯指挥车</h6><p>功能与250/3 Ⅳ型相同，是一种综合型的移动式无线电通讯指挥车。</p><p>250/3 Ⅲ型除配备一台FuG 7型大功率电台通过车后的8米可收放天线作对空联络用外，还配备一台FuG 8型大功率电台通过车体上侧的框形天线作地面部队的联络。但由于该型车配备电台过多造成车内空间过窄，不适宜频繁行动的陆军部队，所以该型车多为配备给空军部队使用（该型车可通过大型运输机运输）。</p>","caption":""}],"part2title":"战场上的250/3型半履带装甲通讯指挥车","part2description":"","part2content":[{"image":"imgs/de/army/de_army_avhtv2503_21.jpg","description":"1941年底，非洲战场利比亚地区，德军第21装甲师指挥官克鲁威尔中将的一辆用250旧车体改装的Sdkfz 250/3 Ⅰ（Alt）型半履带装甲通讯指挥车。","caption":""},{"image":"imgs/de/army/de_army_avhtv2503_22.jpg","description":"1942年，东线苏联战场顿河地区，德军“大德意志”装甲掷弹兵师摩托化营指挥乌泽多姆少校使用的一辆用250旧车体改装的Sdkfz 250/3 Ⅳ（Alt）型半履带装甲通讯指挥车。","caption":""},{"image":"imgs/de/army/de_army_avhtv2503_23.jpg","description":"1943年7月，东线苏联战场库尔斯克地区，隶属德军第6装甲师的一辆用250旧车体改装的Sdkfz 250/3 Ⅰ（Alt）型半履带装甲通讯指挥车；该车仍未改装星形天线，显然属于早期生产的车辆。","caption":""},{"image":"imgs/de/army/de_army_avhtv2503_24.jpg","description":"1943年7月，东线苏联战场哈尔科夫地区，隶属德国武装党卫军第1“阿道夫·希特勒警卫旗队”装甲师的一辆用250旧车体改装的早期Sdkfz 250/3 Ⅰ（Alt）型半履带装甲通讯指挥车。","caption":""},{"image":"imgs/de/army/de_army_avhtv2503_25.jpg","description":"1944年12月，西线战场阿登地区，隶属德国武装党卫军第2“帝国”装甲师的一辆用250新车体改装的Sdkfz 250/3 Ⅳ（Neu）型半履带装甲通讯指挥车。","caption":""},{"image":"imgs/de/army/de_army_avhtv2503_26.jpg","description":"1945年5月，波斯尼亚地区，德国武装党卫军区队长卡尔·冯·皮科勒贝格豪斯的一辆Sdkfz 250/3 Ⅰ（Neu）型半履带装甲通讯指挥车。","caption":""},{"image":"imgs/de/army/de_army_avhtv2503_27.jpg","description":"1942年，一辆奔驰在东线苏联战场上德军连（或营）级指挥官使用的Sdkfz 250/3 Ⅳ（Alt）型半履带装甲通讯指挥车。","caption":""},{"image":"imgs/de/army/de_army_avhtv2503_28.jpg","description":"1942年，东线苏联战场，隶属德军“大德意志”装甲掷弹兵师摩托化营第2连连长使用的一辆Sdkfz 250/3 Ⅳ型半履带装甲通讯指挥车，该车的机枪是MG42型。","caption":""},{"image":"imgs/de/army/de_army_avhtv2503_29.jpg","description":"1942年，东线苏联战场，2辆德军（不明单位）Sdkfz 250/3 Ⅳ（Alt）型半履带装甲通讯指挥车的指挥官正在停下的车辆前观察前方战况。","caption":""},{"image":"imgs/de/army/de_army_avhtv2503_30.jpg","description":"1943年秋天，东线苏联战场，1辆德军（不明单位）的Sdkfz 250/3 Ⅰ（Alt）型半履带装甲通讯指挥车正在一个村庄驶过。","caption":""},{"image":"imgs/de/army/de_army_avhtv2503_31.jpg","description":"这是隶属德国非洲军团指挥官隆美尔元帅军部的Sdkfz 250/3 Ⅳ（Alt）型半履带装甲通讯指挥车，隆美尔元帅正在车上观察并对德军军官作战斗指示。","caption":""},{"image":"imgs/de/army/de_army_avhtv2503_32.jpg","description":"这也是隶属德国非洲军团指挥官隆美尔元帅军部的其中一辆Sdkfz 250/3 Ⅳ（Alt）型半履带装甲通讯指挥车，由隆美尔元帅贴身护卫队军部直属战斗队指挥官鲁道尔夫·基尔上尉使用。","caption":""},{"image":"imgs/de/army/de_army_avhtv2503_33.jpg","description":"1942年初，德国非洲军团属下第90轻装师师长乌里希·在里曼少将在自己的一辆Sdkfz 250/3 Ⅰ（Alt）型半履带装甲通讯指挥车上作战斗指示。","caption":""},{"image":"imgs/de/army/de_army_avhtv2503_34.jpg","description":"这是隶属德军“大德意志”掷弹装甲兵师摩托营营长霍斯特·冯·乌兹得姆的Sdkfz 250/3 Ⅳ（Alt）型半履带装甲通讯指挥车。","caption":""},{"image":"imgs/de/army/de_army_avhtv2503_35.jpg","description":"1944年秋天，西线战场荷兰地区，在一辆Sdkfz 250/3 Ⅰ（Neu）型半履带装甲通讯指挥车上，一名车组成员正用机枪向英国伞兵射击。可见，该型车虽是通讯专用车，但在战场需要时，也得作战斗车辆用。","caption":""},{"image":"imgs/de/army/de_army_avhtv2503_36.jpg","description":"一辆Sdkfz 250/3 Ⅰ型半履带装甲通讯指挥车内的通讯员正在操作大功率无线电台进行发报。从图中可见，此型车厢加装了电台后，空间就显得较狭窄，通讯员工作时也得侧着身子坐。","caption":""},{"image":"imgs/de/army/de_army_avhtv2503_37.jpg","description":"绘画一：在非洲沙漠作战的德军Sdkfz 250/3 Ⅳ型半履带装甲通讯指挥车。","caption":""},{"image":"imgs/de/army/de_army_avhtv2503_38.jpg","description":"绘画二：在非洲沙漠作战的德军Sdkfz 250/3 Ⅳ型半履带装甲通讯指挥车。","caption":""}]}')}});